// Specification for the add_elements function
method add_elements(arr: seq<int>, k: int) returns (result: int)
    requires |arr| > 0          // The array must be non-empty
    requires 1 <= k <= |arr|    // k must be within the bounds of the array length
    ensures result == SumElementsWithTwoDigits(arr, k) // The result is the sum of elements with at most two digits from the first k elements

// Helper function to compute the sum of valid elements
method SumElementsWithTwoDigits(arr: seq<int>, k: int) returns (sum: int)
    ensures sum == Sum(arr[i] | i >= 0 && i < k && abs(arr[i]) < 100) // The sum of elements with at most two digits
{
    sum := 0;
    var i: int := 0;
    while i < k
        invariant 0 <= i <= k // i is always within the bounds
        invariant sum == Sum(arr[j] | j >= 0 && j < i && abs(arr[j]) < 100) // Sum of valid elements seen so far
    {
        if abs(arr[i]) < 100 {
            sum := sum + arr[i];
        }
        i := i + 1;
    }
}
